def valid(projects):
    if not (3 <= len(projects) <= 1000):
        return False
    for p in projects:
        if not (isinstance(p, list) and len(p) == 3 and all(type(v) is int for v in p)):
            return False
        if not (1 <= p[0] <= 1000 and 1 <= p[1] <= 100 and 1 <= p[2] <= 100):
            return False
    return len(set(p[0] for p in projects)) == len(projects)

